#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/syscall_handler.h>
#include <zephyr/fdtable.h>

ZTEST_SUITE(fdtable, NULL, NULL, NULL, NULL, NULL);

ZTEST(fdtable, test_basic_fd_ops)
{
	struct k_fdtable *ft = z_fdtable_get();
	zassert_not_null(ft, "fdtable is NULL");

	struct k_object *obj1 = k_object_alloc(K_OBJ_MEM_SLAB);
	zassert_not_null(obj1, "Failed to allocate obj1");
	int fd1 = z_fdtable_fd_set(ft, obj1);
	zassert_true(fd1 >= 0, "Failed to set fd1");
	zassert_equal(obj1, z_fdtable_fd_get(ft, fd1), "obj1 mismatch");

	struct k_object *obj2 = k_object_alloc(K_OBJ_MEM_SLAB);
	zassert_not_null(obj2, "Failed to allocate obj2");
	int fd2 = z_fdtable_fd_set(ft, obj2);
	zassert_true(fd2 >= 0, "Failed to set fd2");
	zassert_equal(obj2, z_fdtable_fd_get(ft, fd2), "obj2 mismatch");

	z_fdtable_fd_clear(ft, fd1);
	zassert_is_null(z_fdtable_fd_get(ft, fd1), "obj1 not cleared");
	zassert_equal(obj2, z_fdtable_fd_get(ft, fd2), "obj2 unexpectedly cleared");

	z_fdtable_fd_clear(ft, fd2);
	zassert_is_null(z_fdtable_fd_get(ft, fd2), "obj2 not cleared");
}

ZTEST(fdtable, test_invalid_fd_ops)
{
	struct k_fdtable *ft = z_fdtable_get();
	zassert_not_null(ft, "fdtable is NULL");

	zassert_is_null(z_fdtable_fd_get(ft, -1), "Invalid FD -1 should return NULL");
	zassert_is_null(z_fdtable_fd_get(ft, CONFIG_POSIX_MAX_FDS), "Out of bounds FD should return NULL");
	zassert_is_null(z_fdtable_fd_get(ft, CONFIG_POSIX_MAX_FDS + 1), "Out of bounds FD should return NULL");

	z_fdtable_fd_clear(ft, -1);
	z_fdtable_fd_clear(ft, CONFIG_POSIX_MAX_FDS);
}

ZTEST(fdtable, test_fd_reuse)
{
	struct k_fdtable *ft = z_fdtable_get();
	zassert_not_null(ft, "fdtable is NULL");

	struct k_object *obj_a = k_object_alloc(K_OBJ_MEM_SLAB);
	zassert_not_null(obj_a, "Failed to allocate obj_a");
	int fd_a = z_fdtable_fd_set(ft, obj_a);
	zassert_true(fd_a >= 0, "Failed to set fd_a");

	z_fdtable_fd_clear(ft, fd_a);
	zassert_is_null(z_fdtable_fd_get(ft, fd_a), "obj_a not cleared");

	struct k_object *obj_b = k_object_alloc(K_OBJ_MEM_SLAB);
	zassert_not_null(obj_b, "Failed to allocate obj_b");
	int fd_b = z_fdtable_fd_set(ft, obj_b);
	zassert_true(fd_b >= 0, "Failed to set fd_b");

	struct k_object *obj_c = k_object_alloc(K_OBJ_MEM_SLAB);
	zassert_not_null(obj_c, "Failed to allocate obj_c");
	int fd_c = z_fdtable_fd_set(ft, obj_c);
	zassert_true(fd_c >= 0, "Failed to set fd_c");
	zassert_equal(obj_c, z_fdtable_fd_get(ft, fd_c), "obj_c mismatch");
	z_fdtable_fd_clear(ft, fd_c);
}
